#!/usr/bin/env bash
# Gate engine_api_conformance (layer `api`), engine-agnostic: the backend's api/README.md
# manifest matches api/; nothing outside the backend includes a non-api/ header of it;
# every api/ header compiles on its own with the flags of the code that includes it
# (target api_conformance_<engine>, generated by cmake/Backend.cmake). The engine comes
# from the gate context.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
export ROOT

# shellcheck source=aux_gate_common.sh
source "$(dirname "${BASH_SOURCE[0]}")/aux_gate_common.sh"
load_engine_gate_context "${ROOT}" 0

JSON="${ACCEL_GATE_OUT:-/tmp/engine_api_conformance.json}"
fail() { emit_result "${JSON}" engine_api_conformance fail "$1" "${2:-}" "engine=${ENGINE_NAME}"; }

log="$(python3 "${ROOT}/pipeline/gates/check_api_manifest.py" "${ROOT}" "${ENGINE_NAME}" 2>&1)" \
  || fail "api/README.md does not match api/" "${log}"
log="$(python3 "${ROOT}/scripts/check_layer_includes.py" --root "${ROOT}" 2>&1)" \
  || fail "include boundary: only backends/<engine>/api/ may be included from outside the backend" "${log}"
engine_steps "up" "build api_conformance_${ENGINE_NAME}" \
  || fail "an api/ header does not compile on its own: ${ENGINE_FAIL}" "${ENGINE_LOG}"
emit_result "${JSON}" engine_api_conformance pass "" "${ENGINE_LOG}" "engine=${ENGINE_NAME}"
